<script setup lang="ts">import { onMounted, ref } from 'vue'; import AppShell from '@/layouts/AppShell.vue'; import PageHeader from '@/components/PageHeader.vue'; import { connect } from '@/services/connect'; import type { AuditItem } from '@/types/domain'; const items=ref<AuditItem[]>([]); onMounted(async()=>items.value=await connect.audit().catch(()=>[]))</script>
<template><AppShell><PageHeader title="Auditoria" description="Consulte atividades administrativas relevantes."/><div class="timeline"><div v-for="item in items" :key="item.id" class="timeline-item"><i></i><div><strong>{{item.description}}</strong><span>{{item.actor || 'Sistema'}}</span></div><time>{{item.createdAt?new Date(item.createdAt).toLocaleString('pt-BR'):'—'}}</time></div><p v-if="!items.length" class="muted-block">Nenhuma atividade registrada.</p></div></AppShell></template>
